\label{thm:sumprod1}
Fix $t > s > 0$ and $l\in\mathbb{N}$.
Then
\begin{enumerate}[label=$(\alph*)$]
\item \label{thm:sumprod1_a} 
$\begin{aligned}[t]
\sum_{\substack{ s_1, \dots, s_l =\tau_N(s)+1 \\ \text{\normalfont{all distinct}} }}^{\tau_N(t)}
        \prod_{j=1}^l c_N(s_j)
    \leq (t - s + 1)^l \leq (t+1)^l,
\end{aligned}$
\item \label{thm:sumprod1_b} 
$\begin{aligned}[t]
&\Bigg[ (t - s)^l - \Bigg( c_N(\tau_N(s)) + \binom{l}{2} \sum_{r = \tau_N(s) + 1}^{\tau_N(t)} c_N(r)^2 \Bigg) (t + 1)^l \Bigg]  \1{\{ c_N(\tau_N(s)) \leq t - s\}} \\
&\leq \sum_{\substack{ s_1, \dots, s_l =\tau_N(s) + 1 \\ \text{\normalfont{all distinct}} }}^{\tau_N(t)} \prod_{j=1}^l c_N(s_j) \leq (t - s)^l + c_N(\tau_N(t)) (t+1)^l.
\end{aligned}$
\end{enumerate}

 \textbf{\ref{thm:sumprod1_a}}
This follows from the inequalities
\begin{equation*}
\sum_{\substack{ s_1, \dots, s_l =\tau_N(s) + 1 \\ \text{all distinct} }}^{\tau_N(t)}
        \prod_{j=1}^l c_N(s_j)
\leq \Bigg( \sum_{r=\tau_N(s) + 1}^{\tau_N(t)} c_N(r) \Bigg)^l \leq (t - s + 1)^l,
\end{equation*}
the first of which follows from a multinomial expansion of the middle term and the second from Proposition~\ref{thm:cN_properties}\ref{item:cN_property4}. 

\textbf{\ref{thm:sumprod1_b}}
We begin by multiplying the bound in \citet[Supplement, equation (8)]{koskela2022erratum} by $\1{\{ c_N(s) \leq t - s\}}$, which is valid because the left-hand side is non-negative, and yields  
\begin{align*}
&\sum_{\substack{ s_1, \dots, s_l =\tau_N(s) + 1 \\ \text{all distinct} }}^{\tau_N(t)} 
        \prod_{j=1}^l c_N(s_j) \\
