        + \Bigg( \sum_{s=1}^{\tau_N(t)} D_N(s) \Bigg) (t+1)^{l-1} (1+B)^l .
\end{align*}

We start with the binomial expansion
\begin{align}
&\sum_{\substack{ s_1, \dots, s_l =1 \\ \text{all distinct} }}^{\tau_N(t)} 
        \prod_{j=1}^l \left[ c_N(s_j) + B D_N(s_j) \right] \notag \\
&= \sum_{\mathcal{I} \subseteq [l]} B^{l-|\mathcal{I}|}
        \sum_{\substack{ s_1, \dots, s_l =1 \\ \text{all distinct} }}^{\tau_N(t)}
        \Bigg( \prod_{i\in\mathcal{I}} c_N(s_i) \Bigg)
        \Bigg( \prod_{j\notin\mathcal{I}} D_N(s_j) \Bigg). \label{eq:010}
\end{align}
Since we are summing over all permutations of $s_{ 1 : l }$, the inner sum depends on $\mathcal{I}$ only through $I:= |\mathcal{I}|$. We may therefore replace the sum over $\mathcal{I} \subseteq [l]$ with a sum over the size $I$ of the subset and a binomial coefficient counting the number of terms in which the subset is of size $I$:
\begin{align}
&\sum_{\mathcal{I} \subseteq [l]} B^{l-|\mathcal{I}|}
        \sum_{\substack{ s_1, \dots, s_l =1 \\ \text{all distinct} }}^{\tau_N(t)}
        \Bigg( \prod_{i\in\mathcal{I}} c_N(s_i) \Bigg)
        \Bigg( \prod_{j\notin\mathcal{I}} D_N(s_j) \Bigg) \notag\\
&= \sum_{\substack{ s_1, \dots, s_l =1 \\ \text{all distinct} }}^{\tau_N(t)}
        \prod_{j=1}^l c_N(s_j) + \sum_{I=0}^{l-1} \binom{l}{I} B^{l-I} 
        \sum_{\substack{ s_1, \dots, s_l =1 \\ \text{all distinct} }}^{\tau_N(t)}
        \Bigg( \prod_{i=1}^I c_N(s_i) \Bigg) \Bigg( \prod_{j=I+1}^l D_N(s_j) \Bigg), \label{eq:012}
\end{align}
where we have also separated out the $I = l$ term.
There is always at least one $D_N$ factor in the second term on the right-hand side, so using Proposition~\ref{thm:cN_properties}\ref{item:cN_property1}, Lemma \ref{thm:sumprod1}\ref{thm:sumprod1_a}, and the Binomial Theorem, we can write
\begin{align}
\sum_{I=0}^{l-1}\binom{l}{I} B^{l-I} 
        &\sum_{\substack{ s_1, \dots, s_l =1 \\ \text{all distinct} }}^{\tau_N(t)}
        \Bigg( \prod_{i=1}^I c_N(s_i) \Bigg) \Bigg( \prod_{j=I+1}^l D_N(s_j) \Bigg) \notag\\
&\leq \sum_{I=0}^{l-1}\binom{l}{I} B^{l-I} 
        \Bigg( \sum_{\substack{ s_1, \dots, s_{l-1} =1 \\ \text{all distinct} }}^{\tau_N(t)}
        \prod_{i=1}^{l-1} c_N(s_i) \Bigg) 
        \sum_{s_l=1}^{\tau_N(t)} D_N(s_l) \notag\\
&\leq \sum_{I=0}^{l-1}\binom{l}{I} B^{l-I} (t+1)^{l-1}
        \sum_{s=1}^{\tau_N(t)} D_N(s) \notag \\
&\leq \Bigg( \sum_{s=1}^{\tau_N(t)} D_N(s) \Bigg) (t+1)^{l-1} (1+B)^l. \label{eq:013}
\end{align}
Substituting \eqref{eq:013} into \eqref{eq:012} concludes the proof.

