        \prod_{j=1}^l c_N(s_j) \\
    &\phantom{\leq}- \sum_{\substack{l=1 \\ \text{odd} }}^{\tau_N(t)} 
        \alpha_n^l 1_N \frac{1}{l!} 
        \Bigg[ \sum_{\substack{ s_1, \dots, s_l =1 \\ \text{all distinct} }}^{\tau_N(t)}
        \prod_{j=1}^l c_N(s_j)
        - \Bigg( \sum_{s=1}^{\tau_N(t)} D_N(s) \Bigg) 
        (t+1)^{l-1} (1+B_n^\prime)^l \Bigg] \Bigg\} \\
&\leq 1 + \1{E_N^1 \cap E_N^2} \Bigg\{ \sum_{\substack{l=2 \\ \text{even} }}^{\tau_N(t)} 
        \alpha_n^l 1_N \frac{1}{l!} 
        \left\{ t^l + c_N(\tau_N(t)) (t+1)^l \right\} \\
    &\phantom{\leq 1 + \1{E_N^1 \cap E_N^2} \Bigg\{}- \sum_{\substack{l=1 \\ \text{odd} }}^{\tau_N(t)} 
