    &\phantom{\prod_{r=1}^{\tau_N(t)} (1-p_r) \leq 1} + \Bigg( \sum_{s=1}^{\tau_N(t)} c_N(s)^2 \Bigg)
        \frac{1}{2} \alpha_n^2 (t+1)^2 \exp[ \alpha_n 1_N (t+1) ] \notag\\
    &\phantom{\prod_{r=1}^{\tau_N(t)} (1-p_r) \leq 1} + \Bigg( \sum_{s=1}^{\tau_N(t)} D_N(s) \Bigg)
        \exp[ \alpha_n 1_N (t+1) (1+B_n^\prime) ] . \label{eq:021}
\end{align}
The requirement $\tau_N(t) \geq l$ has been dropped in all but the first term, which constitutes adding some positive terms, giving an upper bound.
Now, taking the expectation and limit, then applying \eqref{eq:BJJK_eq3.3}--\eqref{eq:BJJK_eq3.4}, and using Lemmata \ref{thm:indicators_cN}, \ref{thm:indicators_tau} and \ref{thm:indicators_DN} to show that $\lim_{N\to\infty} \mathbb{P} \left[ \{\tau_N(t) \geq l\} \cap E_N^1 \cap E_N^2 \right] =1$,
\begin{align}
\lim_{N\to\infty} \mathbb{E} \Bigg[ \prod_{r=1}^{\tau_N(t)} (1-p_r) \Bigg]
&\leq 1+ \sum_{l=1}^{\infty} (-\alpha_n)^l \frac{1}{l!} t^l
        \lim_{N\to\infty} \mathbb{P} \left[ \{\tau_N(t) \geq l\} \cap E_N^1 \cap E_N^2 \right] \notag\\
    &\qquad+ \lim_{N\to\infty} \mathbb{E} \left[ c_N(\tau_N(t)) \right]
        \exp[ \alpha_n (t+1) ] \notag\\
    &\qquad+ \lim_{N\to\infty} \mathbb{E} \Bigg[ \sum_{s=1}^{\tau_N(t)} 
        c_N(s)^2 \Bigg]
        \frac{1}{2} \alpha_n^2 (t+1)^2 \exp[ \alpha_n (t+1) ] \notag\\
    &\qquad+ \lim_{N\to\infty} \mathbb{E} \Bigg[ \sum_{s=1}^{\tau_N(t)} D_N(s) \Bigg]
        \exp[ \alpha_n (t+1) (1+B_n^\prime) ] \notag\\
&= 1+ \sum_{l=1}^{\infty} (-\alpha_n)^l \frac{1}{l!} t^l
= e^{-\alpha_n t}. \label{eq:022}
\end{align}
Passing the limit and expectation inside the infinite sum is justified by dominated convergence and Fubini's theorem.

It remains to show the corresponding lower bound: $\lim_{N\to\infty} \mathbb{E}[ \prod_{r=1}^{\tau_N(t)} (1-p_r) ] 
\geq e^{-\alpha_n t}$.
Setting $\xi=\Delta$ in Proposition~\ref{thm:pDelta_LB}, we have
\begin{equation}\label{eq:pDeltaDelta_LB}
1-p_t
= p_{\Delta\Delta}(t) \geq 1 - \frac{N^{n-2}}{(N-2)_{n-2}} \alpha_n 
    [ c_N(t) + B_n D_N(t) ] ,
\end{equation}
where $B_n >0$.
Due to Proposition~\ref{thm:cN_properties}\ref{item:cN_property1}, a sufficient condition for this bound to be non-negative is
\begin{equation}\label{eq:defn_E3}
E_N^3(r)
:= \left\{ c_N(r) \leq \frac{(N-2)_{n-2}}{N^{n-2}} 
        \alpha_n^{-1} (1+B_n)^{-1} \right\} ,
\end{equation}
and we define $E_N^3 := \bigcap_{r=1}^{\tau_N(t)} E_N^3(r)$. 
Then
\begin{equation*}
1-p_t
\geq \left\{ 1 - \frac{N^{n-2}}{(N-2)_{n-2}} \alpha_n 
    [ c_N(t) + B_n D_N(t) ] \right\} \1{E_N^3(t)}
\end{equation*}
is also a valid lower bound since if $E_N^3$ does not occur then this collapses to the trivial lower bound $1-p_t \geq 0$.
We now apply a multinomial expansion to the product, and split into positive and negative terms:
\begin{align}
\prod_{r=1}^{\tau_N(t)} (1-p_r)
&\geq \Bigg\{ 1 + \sum_{\substack{l=2 \\ \text{even} }}^{\tau_N(t)} 
        \alpha_n^l 1_N \frac{1}{l!} 
        \sum_{\substack{ s_1, \dots, s_l =1 \\ \text{all distinct} }}^{\tau_N(t)}
        \prod_{j=1}^l
        \left[ c_N(s_j) + B_n D_N(s_j) \right] \nonumber \\
    &\qquad- \sum_{\substack{l=1 \\ \text{odd} }}^{\tau_N(t)} 
        \alpha_n^l 1_N \frac{1}{l!}
        \sum_{\substack{ s_1, \dots, s_l =1 \\ \text{all distinct} }}^{\tau_N(t)}
        \prod_{j=1}^l
        \left[ c_N(s_j) + B_n D_N(s_j) \right] \Bigg\} \1{E_N^3}. \label{eqlabel_1}
\end{align}
From here, the argument for the lower bound follows the same steps as that used to obtain the upper bound.
The right-hand side of \eqref{eqlabel_1} is further bounded via Lemma~\ref{thm:sumprod2} and both bounds in Lemma~\ref{thm:sumprod1}\ref{thm:sumprod1_b}:
\begin{align*}
