&\geq \1{E_N^3} \Bigg\{ 1 + 
        \sum_{\substack{l=2 \\ \text{even} }}^{\tau_N(t)} 
        \alpha_n^l 1_N \frac{1}{l!} 
        \sum_{\substack{ s_1, \dots, s_l =1 \\ \text{all distinct} }}^{\tau_N(t)}
        \prod_{j=1}^l c_N(s_j) - \sum_{\substack{l=1 \\ \text{odd} }}^{\tau_N(t)} 
        \alpha_n^l 1_N \frac{1}{l!} \\
    &\phantom{\geq}\times
        \Bigg[ \sum_{\substack{ s_1, \dots, s_l =1 \\ \text{all distinct} }}^{\tau_N(t)}
        \prod_{j=1}^l c_N(s_j)
        + \Bigg( \sum_{s=1}^{\tau_N(t)} D_N(s) \Bigg)
        (t+1)^{l-1} (1+B_n)^l \Bigg] \Bigg\} \\
&\geq \1{E_N^3} \Bigg\{ 1 + 
        \sum_{\substack{l=2 \\ \text{even} }}^{\tau_N(t)} 
        \alpha_n^l 1_N \frac{1}{l!} 
        \Bigg[ t^l - \Bigg( \sum_{s=1}^{\tau_N(t)} c_N(s)^2 \Bigg)
        \binom{l}{2}(t+1)^l \Bigg] - \sum_{\substack{l=1 \\ \text{odd} }}^{\tau_N(t)} 
        \alpha_n^l \\
    &\phantom{\geq}
        \times 1_N \frac{1}{l!} \Bigg[ t^l + c_N(\tau_N(t)) (t+1)^l
        + \Bigg( \sum_{s=1}^{\tau_N(t)} D_N(s) \Bigg)
        (t+1)^{l-1} (1+B_n)^l \Bigg] \Bigg\} .
\end{align*}
