    &\qquad- \sum_{l=1}^{\tau_N(t) -k}
        (-\alpha_n)^l 1_N \frac{1}{l!}
        \sum_{\substack{s_1, \dots, s_l =1 \\ \text{all distinct}: 
        \\ \exists i,i^\prime : s_i=r_{i^\prime} }}^{\tau_N(t)} 
        \prod_{j=1}^l [ c_N(s_j) - B_n^\prime D_N(s_j) ]
        \1{E_N^1 \cap E_N^2} . \label{eq:031}
\end{align}
The penultimate line above is exactly the expansion we had in the basis step \eqref{eq:019}, except for the upper limit of the summation over $l$, and as such following the same arguments gives a bound analogous to that in \eqref{eq:021}:
\begin{align*}
&1 + \sum_{l=1}^{\tau_N(t) -k}
        (-\alpha_n)^l 1_N \frac{1}{l!}
        \sum_{\substack{ s_1, \dots, s_l =1 \\ \text{all distinct} }}^{\tau_N(t)}
        \prod_{j=1}^l [ c_N(s_j) - B_n^\prime D_N(s_j) ] \1{E_N^1 \cap E_N^2} \\
&\leq 1+ \sum_{l=1}^{\tau_N(t) -k} (-\alpha_n)^l 1_N \frac{1}{l!} t^l
        \1{E_N^1 \cap E_N^2}
        + c_N(\tau_N(t)) \exp[ \alpha_n 1_N (t+1) ] \\
    &\qquad+ \Bigg( \sum_{s=1}^{\tau_N(t)} c_N(s)^2 \Bigg)
        \frac{1}{2} \alpha_n^2 (t+1)^2 \exp[ \alpha_n 1_N (t+1) ] \\
    &\qquad+ \Bigg( \sum_{s=1}^{\tau_N(t)} D_N(s) \Bigg)
        \exp[ \alpha_n 1_N (t+1) (1+B_n^\prime) ] .
\end{align*}
For the last line of \eqref{eq:031}, recalling that $D_N(t) \leq c_N(t)$ (Proposition~\ref{thm:cN_properties}\ref{item:cN_property1}),
\begin{align*}
&- \sum_{l=1}^{\tau_N(t) -k} (-\alpha_n)^l 1_N \frac{1}{l!}
        \sum_{\substack{s_1, \dots, s_l =1 \\ \text{all distinct}: 
        \\ \exists i,i^\prime : s_i=r_{i^\prime} }}^{\tau_N(t)} 
        \prod_{j=1}^l \{ c_N(s_j) - B_n^\prime D_N(s_j) \} 
        \1{E_N^1 \cap E_N^2} \\
&\leq \sum_{l=1}^{\tau_N(t) -k} \alpha_n^l 1_N \frac{1}{l!}
        \sum_{\substack{s_1, \dots, s_l =1 \\ \text{all distinct}: 
        \\ \exists i,i^\prime : s_i=r_{i^\prime} }}^{\tau_N(t)} 
        \prod_{j=1}^l \{ c_N(s_j) + B_n^\prime D_N(s_j) \} \\
&\leq \sum_{l=1}^{\tau_N(t) -k} \alpha_n^l 1_N \frac{1}{l!}
        \sum_{\substack{s_1, \dots, s_l =1 \\ \text{all distinct}: 
        \\ \exists i,i^\prime : s_i=r_{i^\prime} }}^{\tau_N(t)} 
        (1 + B_n^\prime)^l \prod_{j=1}^l c_N(s_j) \\
&\leq \sum_{s \in \{r_1,\dots,r_k\} } c_N(s)
        \sum_{l=1}^{\tau_N(t) -k} \alpha_n^l 1_N
        \frac{1}{(l-1)!}  (1 + B_n^\prime)^l
        \sum_{\substack{ s_1, \dots, s_{l-1} =1 \\ \text{all distinct} }}^{\tau_N(t)}
        \prod_{j=1}^{l-1} c_N(s_j) \\
&\leq \sum_{j=1}^k c_N(r_j)
        \sum_{l=1}^{\tau_N(t) -k} \alpha_n^l 1_N
        \frac{1}{(l-1)!}  (1 + B_n^\prime)^l (t+1)^{l-1} \\
&\leq \left( \sum_{j=1}^k c_N(r_j) \right)
        \alpha_n (1 + B_n^\prime) 
        \exp[ \alpha_n 1_N (1 + B_n^\prime) (t+1) ] ,
\end{align*}
where the penultimate inequality uses Lemma~\ref{thm:sumprod1}\ref{thm:sumprod1_a}.
Substituting the preceding two displays into \eqref{eq:031}, we obtain
\begin{align}
\prod_{\substack{r=1 \\ \notin \{r_1,\dots,r_k\} }}^{\tau_N(t)} (1-p_r)&\leq 1+ \sum_{l=1}^{\tau_N(t) -k} (-\alpha_n)^l 1_N \frac{1}{l!} t^l
        \1{E_N^1 \cap E_N^2}
        + c_N(\tau_N(t)) \exp[ \alpha_n 1_N (t+1) ] \notag\\
    &\qquad+ \left( \sum_{s=1}^{\tau_N(t)} c_N(s)^2 \right)
        \frac{1}{2} \alpha_n^2 (t+1)^2 \exp[ \alpha_n 1_N (t+1) ] \notag\\
    &\qquad+ \left( \sum_{s=1}^{\tau_N(t)} D_N(s) \right)
        \exp[ \alpha_n 1_N (t+1) (1+B_n^\prime) ] \notag\\
    &\qquad+ \left( \sum_{j=1}^k c_N(r_j) \right)
        \alpha_n (1 + B_n^\prime)
        \exp[ \alpha_n 1_N (1 + B_n^\prime) (t+1) ] . \label{eq:034b}
\end{align}
To obtain a corresponding bound for $p_r$, we use \eqref{eq:pDeltaDelta_LB} and Lemma~\ref{thm:sumprod2} (with ordered rather than distinct indices) to obtain
\begin{align}
\sum_{\substack{r_1 <\dots< r_k :\\ r_i \leq \tau_N(t_i) \forall i}}
        \prod_{i=1}^k p_{r_i}
&\leq \alpha_n^k 1_N 
        \sum_{\substack{r_1 <\dots< r_k :\\ r_i \leq \tau_N(t_i) \forall i}}
        \prod_{i=1}^k \left[ c_N(r_i) + B_n D_N(r_i) \right] \notag\\
&\leq \alpha_n^k 1_N
        \sum_{\substack{r_1 <\dots< r_k :\\ r_i \leq \tau_N(t_i) \forall i}}
        \prod_{i=1}^k c_N(r_i) \notag \\
        &\phantom{\leq} + \Bigg( \sum_{s=1}^{\tau_N(t)} D_N(s) \Bigg)
        \alpha_n^k 1_N (t+1)^{k-1} (1+B_n)^k . \label{eq:035}
\end{align}
The following looser but simpler bound will also be useful:
\begin{align}
\prod_{i=1}^k p_{r_i}
\leq \alpha_n^k 1_N 
        \prod_{i=1}^k \left[ c_N(r_i) + B_n D_N(r_i) \right] 
        &\leq \alpha_n^k 1_N  \prod_{i=1}^k c_N(r_i) (1 + B_n) \notag\\
&\leq \alpha_n^k 1_N (1 + B_n)^k
        \prod_{i=1}^k c_N(r_i). \label{eq:036}
\end{align}
Using Lemma~\ref{thm:sumprod1}\ref{thm:sumprod1_a}, \eqref{eq:036} also leads to the deterministic bound
\begin{align}
\sum_{\substack{r_1 <\dots< r_k :\\ r_i \leq \tau_N(t_i) \forall i}}
        \prod_{i=1}^k p_{r_i}
&\leq \alpha_n^k 1_N (1 + B_n)^k \frac{1}{k!}
        \sum_{r_1 \neq \dots\neq r_k}^{\tau_N(t)} 
        \prod_{i=1}^k c_N(r_i) \notag\\
&\leq \alpha_n^k 1_N (1 + B_n)^k \frac{1}{k!} (t+1)^k. 
        \label{eq:037}
\end{align}
