Assume \eqref{eq:mainthmcondition2} holds.
Fix $k \in \mathbb{N}$, $i_0:=0$, $i_k:=k$. 
Let $E_N$ be a sequence of events such that 
$\lim_{N\to\infty} \mathbb{P}[E_N] =1$. 
Then for any sequence of times 
$0 = t_0 \leq t_1 \leq \cdots \leq t_k \leq t$,
\begin{equation*}
\lim_{N\to\infty} \mathbb{E} \Bigg[ \1{E_N} 
        \sum_{\substack{r_1<\dots<r_k :\\ r_i\leq \tau_N(t_i) \forall i}}
        \prod_{i=1}^k c_N(r_i) \Bigg] 
= \sum_{\substack{i_1\leq \dots\leq i_{k-1}\\ \in \{0,\dots,k\} :
        i_j \geq j}}
        \prod_{j=1}^k \frac{(t_j - t_{j-1})^{i_j - i_{j-1}}}{(i_j - i_{j-1})! } .
\end{equation*}

\begin{equation*}
\lim_{N\to\infty} \mathbb{E} \Bigg[ \1{E_N} 
        \sum_{\substack{r_1<\dots<r_k :\\ r_i\leq \tau_N(t_i) \forall i}}
        \prod_{i=1}^k c_N(r_i) \Bigg] 
= \sum_{\substack{i_1\leq \dots\leq i_{k-1}\\ \in \{0,\dots,k\} :
        i_j \geq j}}
        \prod_{j=1}^k \frac{(t_j - t_{j-1})^{i_j - i_{j-1}}}{(i_j - i_{j-1})! } .
\end{equation*}

As pointed out by \citet[p.\ 460]{mohle1999}, the sum-product on the left-hand side of the statement can be expanded as
\begin{equation*}
\sum_{\substack{r_1<\dots<r_k :\\ r_i\leq \tau_N(t_i) \forall i}} 
        \prod_{i=1}^k c_N(r_i)
= \sum_{\substack{i_1\leq \dots\leq i_{k-1}\\ \in \{0,\dots,k\} :
        i_j \geq j}} \, \prod_{j=1}^k \frac{1}{(i_j - i_{j-1})!}
        \sum_{\substack{ r_{i_{j-1}+1}, \ldots, r_{i_j} \\ = \tau_N(t_{j-1})+1 
        \\ \text{all distinct} }}^{\tau_N(t_j)}  
        \,\prod_{i=i_{j-1}+1}^{i_j} c_N(r_i) .
\end{equation*}
By Lemma~\ref{thm:sumprod1}\ref{thm:sumprod1_b},
\begin{align*}
\sum_{\substack{ r_{i_{j-1}+1}, \ldots, r_{i_j} = \tau_N(t_{j-1})+1 
        \\ \text{all distinct} }}^{\tau_N(t_j)}  
        \prod_{i=i_{j-1}+1}^{i_j} c_N(r_i) \leq{}& (t_j - t_{j-1})^{i_j - i_{j-1}} 
        \\& + c_N(\tau_N(t_j)) ( t_j +1 )^{i_j - i_{j-1}}.
\end{align*}
Hence, a $k$-fold product of similar terms can be bounded as
\begin{align*}
&\prod_{j=1}^k \frac{1}{(i_j - i_{j-1})!}
        \sum_{\substack{ r_{i_{j-1}+1}, \ldots, r_{i_j} = \tau_N(t_{j-1})+1 
        \\ \text{all distinct} }}^{\tau_N(t_j)}
        \,\prod_{i=i_{j-1}+1}^{i_j} c_N(r_i) \\
&\leq \prod_{j=1}^k \Bigg\{ \frac{(t_j - t_{j-1})^{i_j - i_{j-1}}}{(i_j - i_{j-1})!} + c_N(\tau_N(t_j)) \frac{( t_j +1 )^{i_j - i_{j-1}}}{(i_j - i_{j-1})!} \Bigg\} 
        \\
&\leq \prod_{j=1}^k \frac{(t_j - t_{j-1})^{i_j - i_{j-1}}}{(i_j - i_{j-1})!}  + \sum_{\mathcal{I} \subset [k]} \left( \prod_{j\in\mathcal{I}} 
        t^{i_j - i_{j-1}}\right)
        \Bigg( \prod_{j\notin\mathcal{I}} c_N(\tau_N(t_j))
        (t+1)^{i_j - i_{j-1}} \Bigg) \\
&\leq  \prod_{j=1}^k \frac{(t_j - t_{j-1})^{i_j - i_{j-1}}}{(i_j - i_{j-1})!}
        + \sum_{\mathcal{I} \subset [k]} c_N(\tau_N(t_{j^\star(\mathcal{I})})) 
        ( t+1 )^k,
\end{align*}
where, say, $j^\star(\mathcal{I}) := \min\{ j\notin\mathcal{I}\}$, and the second-to-last line follows by separating the $I = [k]$ term, and the last via Proposition \ref{thm:cN_properties}\ref{item:cN_property1}, recalling that $t_0 = 0$ and $t = t_k$.
Now we are in a position to evaluate the desired limit: 
\begin{align*}
&\lim_{N\to\infty} \mathbb{E} \Bigg[ \1{E_N} 
        \sum_{\substack{r_1<\dots<r_k :\\ r_i\leq \tau_N(t_i) \forall i}} 
        \prod_{i=1}^k c_N(r_i) \Bigg] 
\leq \lim_{N\to\infty} \mathbb{E} \Bigg[\sum_{\substack{r_1<\dots<r_k :\\ 
        r_i\leq \tau_N(t_i) \forall i}} \prod_{i=1}^k c_N(r_i) \Bigg] \\
&\leq \sum_{\substack{i_1\leq \dots\leq i_{k-1}\\ \in \{0,\dots,k\} :
        i_j \geq j}} \Bigg\{ \prod_{j=1}^k \frac{(t_j - t_{j-1})^{i_j - i_{j-1}}}
        {(i_j - i_{j-1})!} + \sum_{\mathcal{I} \subset [k]} \lim_{N\to\infty} 
        \mathbb{E} [ c_N(\tau_N(t_{j^\star(\mathcal{I})})) ] 
        (t+1)^k \Bigg\} \\
&= \sum_{\substack{i_1\leq \dots\leq i_{k-1}\\ \in \{0,\dots,k\} : 
        i_j \geq j \forall j}} \prod_{j=1}^k \frac{(t_j - t_{j-1})^{i_j - i_{j-1}}}
        {(i_j - i_{j-1})!},
\end{align*}
using \eqref{eq:BJJK_eq3.3}.
For the corresponding lower bound, by Lemma~\ref{thm:sumprod1}\ref{thm:sumprod1_b},
\begin{align*}
&\sum_{\substack{ r_{i_{j-1}+1}, \ldots, r_{i_j} = \tau_N(t_{j-1})+1 
        \\ \text{all distinct} }}^{\tau_N(t_j)}  
        \prod_{i=i_{j-1}+1}^{i_j} c_N(r_i)  \\ 
&\geq \Bigg[(t_j - t_{j-1})^{i_j - i_{j-1}} - \Bigg(c_N(\tau_N(t_{j - 1}))  \\
        &\phantom{\geq \Bigg[} + \binom{i_j - i_{j-1}}{2} \sum_{s=\tau_N(t_{j-1})+1}^{\tau_N(t_j)}
        c_N(s)^2 \Bigg) ( t_j + 1 )^{i_j - i_{j-1}} \Bigg] \1{\{c_N(\tau_N(t_{j - 1})) \leq t_j - t_{j - 1}\}}.
\end{align*}
Define the events
\begin{align*}
E_N^4(j)
&= \Bigg\{ \sum_{s=\tau_N(t_{j-1})+1}^{\tau_N(t_j)} c_N(s)^2
        \leq \frac{1}{2(i_j - i_{j - 1})!} \Bigg( \frac{ t_j - t_{j-1} }{ t_j +1 }\Bigg)^{i_j - i_{j-1}} \Bigg\}, \\
F_N^4(j)
&= \Bigg\{ c_N(\tau_N(t_{j-1}))
        \leq \frac{1}{2(i_j - i_{j - 1})!} \Bigg( \frac{ t_j - t_{j-1} }{ t_j +1 }\Bigg)^{i_j - i_{j-1}} \Bigg\},    
\end{align*}
where the upper bound on the right-hand sides is strictly positive since $t_j > t_{j - 1}$, and thus satisfies the conditions of Lemmata \ref{thm:indicators_cN} and \ref{thm:indicators_c2}.
