\begin{equation*}
    E_N^4 := \bigcap_{j=1}^k [E_N^4(j) \cap F_N^4(j) \cap \{c_N(\tau_N(t_{j-1})) \leq t_j - t_{j - 1}\}],
\end{equation*}
on which the factors of the following product are non-negative:
\begin{align*}
&\prod_{j=1}^k \frac{1}{(i_j - i_{j-1})!}
        \sum_{\substack{ r_{i_{j-1}+1}, \ldots, r_{i_j} = \tau_N(t_{j-1})+1 
